/* Types */
export type ActivityEvent = {
	id: string,
	sessionId: string,
	timestamp: string,
	clientHint: string | null,
	tool: string,
	// `"read"` or `"write"`.
	kind: string,
	connectionId: string | null,
	connectionName: string | null,
	// JSON text of the (possibly compacted) arguments.
	targetJson: string | null,
	status: ActivityStatus,
	durationMs: number,
	error: string | null,
	approvalId: string | null,
};

export type ActivityExportFormat = "json" | "csv";

export type ActivityFilter = {
	// RFC 3339, inclusive.
	from: string | null,
	to: string | null,
	clientHint: string | null,
	connectionId: string | null,
	// `"read"` or `"write"`.
	kind: string | null,
	status: ActivityStatus | null,
	sessionId: string | null,
};

export type ActivitySession = {
	sessionId: string,
	clientHint: string | null,
	startedAt: string,
	lastAt: string,
	total: number,
	writes: number,
	// Calls that did not succeed, whatever the reason.
	notSuccessful: number,
};

/**
 *  Outcome of a tool call as the log records it. The four middle values are
 *  the gate's verdicts (`data.kind` of the MCP error).
 */
export type ActivityStatus = "success" | "error" | "blocked_readonly" | "denied" | "timeout" | "host_unavailable";

export type AddConnectionArgs = {
	name: string,
	// The kind of backend that serves it (`bullmq-redis`).
	backend: string,
	/**
	 *  Where that backend is reached, as it describes it. Checked by the
	 *  backend of its kind before anything is written. Never a secret.
	 */
	endpoint: JsonValue,
	/**
	 *  The connection's secret, stored at `{id}` in the keychain. `None` /
	 *  `Some("")` → no password stored.
	 */
	password: string | null,
	/**
	 *  SSH password. Only meaningful when the endpoint's tunnel uses
	 *  password auth. `None` / `Some("")` → no password stored.
	 *  `Some(value)` → stored at `{id}::ssh` in the keychain.
	 */
	sshPassword: string | null,
	/**
	 *  The group this connection belongs to (existing id, or a
	 *  name to find-or-create). Chosen explicitly by the user.
	 */
	group: GroupSelector,
	/**
	 *  The environment within that group (existing id, or a name
	 *  and color to find-or-create). The color is an attribute of the
	 *  environment; it is never used to pick one.
	 */
	environment: EnvironmentSelector,
	/**
	 *  "Read-only until I unlock it". `None` = the production
	 *  default (locked in a Production environment, open elsewhere).
	 */
	locked?: boolean | null,
};

// Args for `add_job`.
export type AddJobArgs = {
	connectionId: string,
	queueId: QueueId,
	job: NewJob,
};

/**
 *  The job Ranch created. `state` is where BullMQ's rules put it: `waiting`,
 *  `paused` (queue paused), `delayed` or `prioritized`.
 */
export type AddJobResult = {
	jobId: string,
	state: JobState,
};

export type AgentApp = "claudeDesktop" | "cursor";

export type AnnotateCauseArgs = {
	connectionId: string,
	queueId: QueueId,
	queueName: string,
	signature: string,
	text: string,
	steps?: string[],
	jobsRead?: string[],
};

export type ApprovalDecision = "approve" | "deny";

/**
 *  Agents › Approvals: the requests already decided (approved,
 *  denied, expired, consumed), newest first, with their connection.
 */
export type ApprovalHistoryItem = {
	id: string,
	createdAt: string,
	decidedAt: string | null,
	// `approved`, `denied`, `expired` or `consumed` (approved, then used).
	status: string,
	clientHint: string | null,
	tool: string,
	reason: string | null,
	connectionId: string,
	// `None` when the connection was removed since.
	connectionName: string | null,
};

/**
 *  Global approval mode: off, writes only, or all. Not per connection: the
 *  per-connection dimension is MCP read-only.
 */
export type ApprovalMode = 
// Never ask. Writes fall through to the session lock.
"off" | 
// Ask for every write tool. **Default.**
"writes_only" | 
// Ask for every tool, reads included.
"all";

/**
 *  What the audit log says about the approval behind an agent
 *  write: who asked, what was decided, when.
 */
export type ApprovalRecord = {
	id: string,
	createdAt: string,
	decidedAt: string | null,
	// `pending`, `approved`, `denied`, `expired` or `consumed` (approved, then used).
	status: string,
	clientHint: string | null,
	tool: string,
	reason: string | null,
	// The exact arguments the agent sent (JSON text).
	argumentsJson: string,
};

export type AttentionItem = {
	// Stable across reads: what a mute remembers.
	key: string,
	kind: AttentionKind,
	connectionId: string,
	connectionName: string,
	envColor: string,
	envLabel: string,
	// The queue, or the one queue of a cause; `None` for a connection.
	queueId: QueueId | null,
	queueName: string | null,
	/**
	 *  Failing: the cause's signature. Stuck: `paused` or `noWorker`.
	 *  Offline: what Redis (or the network) said.
	 */
	reason: string,
	// Failing: the newest reason as written.
	sample: string | null,
	// Failing: failed jobs of the cause. Stuck: jobs waiting.
	count: number,
	/**
	 *  Since when (ms): first failure of the cause, the pause (from the
	 *  audit log), `None` when not known.
	 */
	sinceMs: number | null,
	// Failing: failures per hour over the last 24 hours.
	trend: number[],
	// Failing: the cause's jobs, for "Retry N".
	jobs: JobRef[],
};

export type AttentionKind = "failing" | "stuck" | "offline";

export type AttentionReport = {
	// Most urgent first.
	items: AttentionItem[],
	connectionsChecked: number,
};

export type AuditAction = "retryJob" | "removeJob" | "promoteJob" | "pauseQueue" | "resumeQueue" | "pauseScheduler" | "resumeScheduler" | "unlockConnection" | "lockConnection" | 
// A job enqueued from Ranch (UI or agent).
"addJob" | 
// queue-level maintenance.
"drainQueue" | "cleanQueue" | "retryAllFailed" | 
// A job scheduler created / changed, or deleted.
"upsertScheduler" | "removeScheduler";

/**
 *  Stored shape returned by `list_audit_log_entries` and emitted by
 *  `export_audit_log`. Includes the auto-generated `id` and `created_at`.
 */
export type AuditLogEntry = {
	id: string,
	createdAt: string,
	source: AuditSource,
	operatorId: string,
	agentClient: string | null,
	agentTransport: string | null,
	action: AuditAction,
	target: AuditTarget,
	outcome: AuditOutcome,
	outcomeReason: string | null,
	connectionId: string | null,
	connectionName: string | null,
	envColor: string | null,
	/**
	 *  The group and environment the connection sits
	 *  in *now*, joined at read time: three connections can share a name
	 *  (one per environment) and the snapshot alone cannot tell them apart.
	 *  `None` once the connection is deleted; the snapshot fields above stay.
	 */
	groupName: string | null,
	environmentName: string | null,
	// Set when a human approval authorized this agent write.
	approvalId: string | null,
};

// Outcome of the action: did it succeed, fail, or cancel mid-flight?
export type AuditOutcome = "success" | "failure" | "cancelled";

/**
 *  Who initiated the action: a human via the Ranch UI, or an agent
 *  via the MCP server (the MCP server populates the agent path).
 */
export type AuditSource = "ui" | "agent";

export type AuditTarget = 
// A row written before targets carried the queue's id has none.
{ kind: "job"; data: {
	queueId: QueueId | null,
	queueName: string,
	jobId: string,
} } | { kind: "queue"; data: {
	queueId: QueueId | null,
	queueName: string,
} } | { kind: "scheduler"; data: {
	queueId: QueueId | null,
	queueName: string,
	schedulerKey: string,
} } | { kind: "connection" } | 
/**
 *  A bulk action over a list of jobs within a single
 *  queue. ONE audit row per bulk attempt (regardless of how many
 *  jobs were touched). The `outcome_reason` field carries a
 *  summary of partial-failure detail. The frontend's
 *  `formatAuditTarget` renders this as `{queueName} / {jobCount} jobs`.
 */
{ kind: "bulkJobs"; data: {
	queueId: QueueId | null,
	queueName: string,
	jobCount: number,
} };

/**
 *  One kind of backend, as the connection form offers it: its kind (what
 *  a connection's `backend` holds), its label, what its endpoint asks, and
 *  what every connection of the kind can do.
 */
export type BackendInfo = {
	kind: string,
	label: string,
	endpointSchema: EndpointSchema,
	capabilities: CapabilityDescriptor,
};

// BullMQ's built-in backoff strategies (`opts.backoff`).
export type Backoff = {
	kind: BackoffKind,
	delayMs: number,
};

export type BackoffKind = "fixed" | "exponential";

/**
 *  Input for a bulk action over a list of jobs within a
 *  single queue; cross-queue scope is not supported.
 */
export type BulkActionArgs = {
	connectionId: string,
	queueId: QueueId,
	jobIds: string[],
};

/**
 *  Outcome of a bulk action. The frontend's
 *  `BulkActionBar` renders the summary from these fields. `cancelled`
 *  is true when the actor's cancellation token fired mid-loop
 *  (frontend-abandons-promise path = stays false; only true if the
 *  actor is shutdown).
 */
export type BulkActionResult = {
	action: string,
	total: number,
	succeeded: number,
	failed: BulkFailure[],
	cancelled: boolean,
};

// per-job failure entry collected during a bulk run.
export type BulkFailure = {
	jobId: string,
	reason: string,
};

/**
 *  Typed progress event emitted by the actor every N
 *  completed jobs (see `BULK_PROGRESS_CHUNK` for chunk size). The
 *  frontend subscribes via `@tauri-apps/api/event::listen("bulk:progress")`
 *  and drives the progress bar live.
 * 
 *  `queue_id` tells concurrent per-queue progress streams apart during a
 *  cross-queue bulk run.
 */
export type BulkProgressEvent = {
	action: string,
	queueId: QueueId,
	total: number,
	completed: number,
	failedSoFar: number,
};

/**
 *  The endpoint of a `bullmq-redis` connection, as its JSON reads: the
 *  front end and the tests build and read it with this type. The BullMQ
 *  backend checks it (`adapters::bullmq_redis::endpoint`). No password:
 *  those are sent apart, to the secret store.
 */
export type BullmqRedisEndpoint = {
	host: string,
	port: number,
	db: number,
	username: string | null,
	tls: boolean,
	/**
	 *  A CA added to the system trust roots for TLS. A public certificate,
	 *  not a secret.
	 */
	tlsCustomCa: string | null,
	sshTunnel: SshTunnelConfig | null,
};

/**
 *  Detected BullMQ schema for a connection. Resolved once at connection-
 *  open time (the `ConnectionActor`) by reading the queue meta
 *  hash; cached on the actor for the connection's lifetime. Re-detected
 *  on every app launch (we don't persist it in SQLite: the version of the
 *  remote BullMQ deployment is the authoritative source).
 */
export type BullmqSchema = { kind: "v5" } | { kind: "v6" } | 
/**
 *  The remote BullMQ deployment's `version` field doesn't match a
 *  supported major. The frontend surfaces this verbatim so the user
 *  can file a compatibility issue or upgrade Ranch.
 */
{ kind: "unknown"; detectedVersion: string | null };

/**
 *  What every connection of a kind can do, known without connecting. A
 *  screen offers what is declared; an operation still refuses the rest.
 */
export type CapabilityDescriptor = {
	// The states the backend keeps, in the order a queue shows them.
	jobStates: JobStateInfo[],
	jobActions: JobActionCapabilities,
	maintenance: MaintenanceCapabilities,
	// Pausing and resuming a queue.
	queueControl: boolean,
	schedules: ScheduleCapabilities,
	workers: WorkerCapabilities,
	// Parent and child jobs.
	flows: boolean,
	metrics: MetricsCapabilities,
	events: EventCapabilities,
	server: ServerCapabilities,
};

export type CauseNote = {
	id: string,
	connectionId: string,
	// `None` once the connection was removed.
	connectionName: string | null,
	queueId: QueueId,
	// The queue's name when the note was written, for display.
	queueName: string,
	// The cause, as `list_failure_causes` names it.
	signature: string,
	text: string,
	steps: string[],
	// The agent client that wrote it (`None` = written in Ranch).
	clientHint: string | null,
	createdAt: string,
	// The jobs the agent read to write it.
	jobsRead: string[],
	dismissedAt: string | null,
};

export type ChangeEnvironmentColorArgs = {
	environmentId: string,
	colorToken: string,
};

// Args for `clean_queue`.
export type CleanQueueArgs = {
	connectionId: string,
	queueId: QueueId,
	state: CleanState,
	// Only jobs that finished more than this long ago. `0` = all.
	olderThanMs: number,
};

/**
 *  Finished states `clean` works on. (Jobs that have not started are
 *  `drain`'s business; active jobs are nobody's.)
 */
export type CleanState = "completed" | "failed";

export type Connection = {
	id: string,
	environmentId: string,
	groupId: string,
	name: string,
	// The kind of backend that serves it (`bullmq-redis`).
	backend: string,
	/**
	 *  Where that backend is reached, as it describes it: for
	 *  `bullmq-redis`, a `BullmqRedisEndpoint`. Never holds a secret.
	 */
	endpoint: JsonValue,
	envColor: string,
	envName: string,
	envLabel: string,
	groupName: string,
	createdAt: string,
	/**
	 *  MCP read-only override: `Some(true)` = agents can
	 *  only read, `Some(false)` = agents may write (subject to approval),
	 *  `None` = follow the global default. Visible to agents too, so they
	 *  can tell up-front that a write would be refused.
	 */
	mcpReadonly: boolean | null,
	/**
	 *  The connection is folded in the sidebar (its queues
	 *  hidden). UI state, persisted so it survives a restart.
	 */
	sidebarCollapsed: boolean,
};

/**
 *  What the new-connection sheet shows once the test
 *  succeeds: how fast, and what BullMQ holds there.
 */
export type ConnectionProbe = {
	// Round trip of one `PING`, ms.
	latencyMs: number,
	// BullMQ queues found (`…:meta` keys, bounded scan).
	queuesFound: number,
	// A few of them, `prefix:name`, sorted.
	queueSample: string[],
	// The scan stopped before the end: there may be more queues.
	scanCapped: boolean,
	// Job schedulers across the queues found.
	schedulers: number,
	// BullMQ workers connected; `None` when the server refuses `CLIENT LIST`.
	workers: number | null,
};

// Args for `count_queue_workers`.
export type CountQueueWorkersArgs = {
	connectionId: string,
	queueIds: QueueId[],
};

export type CreateEnvironmentArgs = {
	groupId: string,
	name: string,
	colorToken: string,
};

export type CreateGroupArgs = {
	name: string,
};

/**
 *  BullMQ repeatable / scheduler job. One row in the
 *  `bull:{queue}:repeat` ZSET, decoded from the per-scheduler hash.
 * 
 *  Exactly one of `pattern` / `every` is set for a valid scheduler:
 *  `pattern` carries the cron expression (e.g. `0 9 * * *`); `every`
 *  carries the fixed-interval millisecond delay. The
 *  `handle_list_cron_jobs` skips (with `tracing::warn!`) any hash that
 *  has neither or both.
 * 
 *  `next_run` comes from the ZSET score (ms since epoch). `iteration_count`
 *  comes from the `ic` hash field (the count of past iterations).
 */
export type CronJob = {
	/**
	 *  Scheduler key: BullMQ's stable identifier (the developer-supplied
	 *  id passed to `upsertJobScheduler`).
	 */
	key: string,
	// The job name that BullMQ enqueues on each iteration.
	name: string,
	// Cron expression. Mutually exclusive with `every`.
	pattern: string | null,
	// Fixed interval in milliseconds. Mutually exclusive with `pattern`.
	every: number | null,
	// Optional IANA timezone string (e.g. `Europe/Paris`).
	tz: string | null,
	/**
	 *  BullMQ-internal scheduling offset in ms. Surfaced for debugging;
	 *  the UI hides it from the default columns.
	 */
	offset: number | null,
	/**
	 *  Iteration count: number of times this scheduler has already
	 *  fired. From the `ic` hash field.
	 */
	iterationCount: number,
	// Next scheduled run timestamp (ms since epoch). From the ZSET score.
	nextRun: number,
	/**
	 *  Optional end-of-schedule timestamp (ms since epoch). After this,
	 *  BullMQ stops re-arming the scheduler.
	 */
	endDate: number | null,
	/**
	 *  Raw JSON template attached to enqueued jobs (BullMQ stores it as
	 *  a JSON string in the `data` hash field). Validated as parseable
	 *  JSON at decode time; transmitted as the raw string so the
	 *  frontend can `JSON.parse(template)` on demand. None when the
	 *  scheduler has no template (the common case).
	 */
	template: string | null,
	/**
	 *  Pause flag. `true` when the scheduler has been
	 *  paused via `pause_scheduler` (its entry is removed from the
	 *  `:repeat` ZSET and the per-scheduler hash carries
	 *  `paused = "1"`). The frontend's CronJobsView shows a "Paused"
	 *  badge + a "Resume" button on these rows. `false` is the
	 *  default for running schedulers.
	 */
	paused: boolean,
};

// Result of a GUI decision.
export type DecideOutcome = "decided" | 
/**
 *  The request was no longer pending (already decided, expired, purged).
 *  A no-op by design: the UI just moves on.
 */
"alreadyDecided";

export type DecidePendingApprovalArgs = {
	approvalId: string,
	decision: ApprovalDecision,
	// Optional, shown to the agent when denying.
	reason: string | null,
};

export type DeleteGroupArgs = {
	id: string,
	/**
	 *  `false` → only an empty group may be deleted; a group that still holds
	 *  connections is rejected with `GroupNotEmpty` so the UI can show the
	 *  confirmation listing them. `true` → the confirmed cascade.
	 */
	cascade: boolean,
};

// Args for `drain_queue`.
export type DrainQueueArgs = {
	connectionId: string,
	queueId: QueueId,
	// Also remove delayed jobs (default: yes).
	includeDelayed: boolean,
};

export type DuplicateConnectionArgs = {
	id: string,
};

export type EndpointField = {
	// The key in the endpoint; for a secret, the argument it is sent in.
	key: string,
	label: string,
	kind: FieldKind,
	required: boolean,
	// What a new connection starts with.
	default: JsonValue | null,
};

// What a backend's endpoint holds, field by field.
export type EndpointSchema = {
	fields: EndpointField[],
};

/**
 *  agent-readable shape of an environment row. The UI today
 *  derives the env list from `list_connections` join data; MCP needs a
 *  direct fetch so an agent can enumerate environments without listing
 *  every connection.
 */
export type Environment = {
	id: string,
	groupId: string,
	/**
	 *  Lets an agent (and the "Move to…" menu) say
	 *  "Lumen / Production" without a second lookup.
	 */
	groupName: string,
	label: string,
	colorToken: string,
	name: string,
};

/**
 *  Which environment a connection goes into. `New` is find-or-create by label
 *  within the group; when the label already exists, the existing environment
 *  (and its color) wins. The color is an attribute of the environment and
 *  is **never** used to pick one.
 */
export type EnvironmentSelector = { kind: "existing"; id: string } | { kind: "new"; name: string; colorToken: string };

export type EventCapabilities = {
	read: boolean,
	// Followed live, so windows refresh what moved instead of polling.
	follow: boolean,
};

// Where the last read of a queue stopped (a stream id).
export type EventCursor = {
	queueId: QueueId,
	lastId: string,
};

export type ExportAuditLogArgs = {
	from: string | null,
	to: string | null,
	connectionId: string | null,
	action: string | null,
	source: string | null,
	// `"json"` | `"csv"`.
	format: string,
};

export type ExportMcpActivityArgs = {
	filter: ActivityFilter,
	format: ActivityExportFormat,
};

export type ExportResult = {
	content: string,
	suggestedFilename: string,
};

// One page of the cross-queue failed view.
export type FailedJobsPage = {
	// Newest failure first. `state` is always `failed`.
	jobs: Job[],
	// Jobs matching the filter among the scanned ones: what pagination runs on.
	total: number,
	// Every failed job on the connection (sum of the queues' counts), exact.
	totalFailed: number,
	// Per-queue counts, most failing first; queues without failures omitted.
	queues: FailedQueueCount[],
	/**
	 *  Most failing job types among the scanned jobs (before the name /
	 *  reason filter, so the summary stays a way to *choose* a filter).
	 */
	types: FailingJobType[],
	// How many of the newest failed jobs were looked at…
	scanned: number,
	// …and whether older ones exist beyond the scan.
	scanCapped: boolean,
	// Queues whose failed set could not be read (reported, not fatal).
	unreadableQueues: string[],
};

export type FailedQueueCount = {
	queueId: QueueId,
	queueName: string,
	// `ZCARD` of the queue's failed set, exact.
	failed: number,
};

export type FailingJobType = {
	queueId: QueueId,
	queueName: string,
	name: string,
	count: number,
	lastFailedAt: number,
	lastReason: string | null,
};

// One cause: the failures whose reasons only differ by the values in them.
export type FailureCause = {
	/**
	 *  The reason with its values replaced (`<n>`, `<str>`, `<url>`…).
	 *  Empty = the jobs recorded no reason.
	 */
	signature: string,
	// The newest reason of the cause, as written.
	sample: string,
	count: number,
	firstAt: number,
	lastAt: number,
	// Job types of the cause, most frequent first (at most five).
	jobNames: string[],
	// Queues of the cause, most frequent first.
	queueNames: string[],
	// Failures per hour over the last 24 hours, oldest first.
	trend: number[],
	/**
	 *  Every scanned job of the cause, newest first: what "Retry N" and
	 *  "Remove N" act on.
	 */
	jobs: JobRef[],
};

// The failed jobs of a queue (or of a connection), grouped by cause.
export type FailureCauses = {
	// Most frequent first.
	causes: FailureCause[],
	// Failed jobs looked at…
	scanned: number,
	// …and whether older ones exist beyond the scan.
	scanCapped: boolean,
	// Every failed job of the queue / connection, exact.
	totalFailed: number,
	// Queues whose failed set could not be read (reported, not fatal).
	unreadableQueues: string[],
};

/**
 *  How a field is entered. A `secret` is sent apart from the endpoint and
 *  kept in the secret store; the `sshTunnel` group's password too.
 */
export type FieldKind = "text" | "number" | "boolean" | "secret" | "pem" | "sshTunnel";

export type FlowLink = {
	parent: QueueId,
	child: QueueId,
	// Child jobs seen on the link (among the newest parents).
	jobs: number,
};

/**
 *  One job of a flow. The tree is flat (`parent_key` links the nodes) so
 *  it crosses the IPC boundary without recursive types and feeds a graph
 *  layout directly.
 */
export type FlowNode = {
	// `{prefix}:{queue}:{id}`, unique within the flow.
	key: string,
	jobRef: JobRef,
	// `None` for the root.
	parentKey: string | null,
	name: string,
	state: JobState,
	timestamp: number | null,
	// `finishedOn − processedOn`, when both are known.
	durationMs: number | null,
	failedReason: string | null,
	/**
	 *  The job hash no longer exists (removed by `removeOnComplete`, a clean…):
	 *  the parent still references it.
	 */
	missing: boolean,
	// What a finished job returned (raw JSON), if anything.
	returnValue?: string | null,
	/**
	 *  This job failed for good and its parent waits for it
	 *  forever (no `failParentOnFailure` / `ignoreDependencyOnFailure`…).
	 */
	blocksParent?: boolean,
};

// A flow root found in a queue (the queue's Flows tab).
export type FlowRoot = {
	jobRef: JobRef,
	name: string,
	state: JobState,
	timestamp: number | null,
	// Direct children, by what became of them.
	childrenTotal: number,
	childrenPending: number,
	childrenCompleted: number,
	childrenFailed: number,
	// The root waits on a child that failed for good.
	blocked?: boolean,
};

export type FlowRoots = {
	// Newest first.
	roots: FlowRoot[],
	// Jobs looked at.
	scanned: number,
	/**
	 *  The queue holds more finished jobs than discovery looks at: older
	 *  flows are not listed.
	 */
	capped: boolean,
};

export type FlowTree = {
	// Root first, then breadth-first.
	nodes: FlowNode[],
	rootKey: string,
	// The job the flow was asked for.
	focusKey: string,
	// The flow holds more than [`MAX_NODES`] jobs; the rest is not shown.
	truncated: boolean,
	// A parent waits on a child that failed for good.
	blocked?: boolean,
};

/**
 *  Follow (or stop following) a connection's BullMQ event
 *  streams. Each window that follows counts; the reading stops when the
 *  last one stops.
 */
export type FollowConnectionEventsArgs = {
	connectionId: string,
	follow: boolean,
};

/**
 *  connection-level overview that aggregates metrics
 *  across every queue on the connection. Frontend uses this for the
 *  env-level dashboard at `/connections/$id/`.
 */
export type GetConnectionMetricsArgs = {
	connectionId: string,
	// The window (5m … 7d). Defaults to 24h.
	range?: MetricsRange,
};

export type GetJobArgs = {
	connectionId: string,
	queueId: QueueId,
	jobId: string,
};

export type GetJobLogsArgs = {
	connectionId: string,
	queueId: QueueId,
	jobId: string,
	// 0-based offset into the logs list. Default 0.
	offset: number,
	/**
	 *  Page size. The frontend uses 200 by default; that covers
	 *  the realistic case; pathological multi-thousand-line cases get
	 *  pagination via Previous/Next.
	 */
	limit: number,
};

export type GetQueueMetricsArgs = {
	connectionId: string,
	queueId: QueueId,
	// The window (5m … 7d). Defaults to 24h.
	range?: MetricsRange,
	/**
	 *  "now" (ms), so that every queue of a connection-level call
	 *  is bucketed against the same instant. `None` = the actor's clock.
	 */
	nowMs?: number | null,
};

export type GetServerInfoArgs = {
	connectionId: string,
};

/**
 *  Completed / failed over time for every queue of a
 *  connection, from native metrics. Cheap: two reads per queue, one
 *  pipeline, no job sampling.
 */
export type GetThroughputArgs = {
	connectionId: string,
	// 1h, 6h or 24h are what the screens ask for; any window works.
	range?: MetricsRange,
};

// Flow links between queues, added per minute, oldest waiting.
export type GetTopologyArgs = {
	connectionId: string,
};

export type Group = {
	id: string,
	name: string,
	displayOrder: number,
	collapsed: boolean,
	/**
	 *  Number of connections under this group (across all its environments).
	 *  Lets the sidebar decide between "delete immediately" and "confirm the
	 *  cascade" without a second round-trip.
	 */
	connectionCount: number,
};

/**
 *  Which group a connection goes into. `New` is find-or-create: a name that
 *  already exists (case-insensitively) resolves to that group, so a retried
 *  save can never produce two "Lumen" groups.
 */
export type GroupSelector = { kind: "existing"; id: string } | { kind: "new"; name: string };

// How a client is wired up.
export type InstallerKind = 
// Ranch merges `mcpServers.ranch` into the client's JSON config.
"jsonMerge" | 
/**
 *  The client owns its config; Ranch asks the client's own CLI to
 *  register the server (`claude mcp add …`, `codex mcp add …`).
 */
"clientCli";

/**
 *  A single decoded BullMQ job. All fields except `data` / `opts` /
 *  `return_value` / `parent_key` are direct field translations from the
 *  Redis hash; the JSON-encoded ones are parsed once at decode time so
 *  feature code receives structured `serde_json::Value`.
 * 
 *  `state` is the heuristic state inferred from job-hash fields alone.
 *  Callers performing a list-membership query can override it.
 */
export type Job = {
	jobRef: JobRef,
	name: string,
	state: JobState,
	/**
	 *  Job payload: the raw JSON-encoded string BullMQ stored in the
	 *  `data` field. The decoder VALIDATES that this is parseable JSON
	 *  (returns `SchemaError::InvalidJson` if not), but stores the
	 *  original string so the wire shape stays simple. The frontend
	 *  parses on demand: `JSON.parse(job.data)`.
	 */
	data: string,
	/**
	 *  Job options: same treatment as `data`. Validated as JSON at
	 *  decode time, transmitted as the raw string.
	 */
	opts: string,
	attemptsMade: number,
	// Milliseconds since epoch (BullMQ convention).
	timestamp: number,
	processedOn: number | null,
	finishedOn: number | null,
	delay: number | null,
	failedReason: string | null,
	/**
	 *  Stacktrace lines as parsed from the `stacktrace` field (BullMQ
	 *  JSON-encodes a `String[]`). Empty vec when no stacktrace stored.
	 */
	stacktrace: string[],
	/**
	 *  Job return value: raw JSON-encoded string when present (BullMQ
	 *  stores this for completed jobs in the `returnvalue` field).
	 *  `None` when the field is absent or unparseable JSON. Validated at
	 *  decode time but transmitted as the raw string.
	 */
	returnValue: string | null,
	// Parent flow-job key, when this job is a child in a BullMQ flow.
	parentKey: string | null,
	/**
	 *  What the worker reported with `job.updateProgress()`: the
	 *  raw JSON text, a number (`42`) or an object (`{"step":"upload"}`).
	 *  `None` when absent or still at BullMQ's initial `0`.
	 */
	progress: string | null,
	/**
	 *  The worker that took the job (`pb`, BullMQ ≥ 5), when
	 *  it says.
	 */
	processedBy?: string | null,
	/**
	 *  Time left on the job's lock (`…:lock`, ms) while a
	 *  worker holds it; a worker renews it as long as the job runs. Only
	 *  read for running jobs.
	 */
	lockTtlMs?: number | null,
};

/**
 *  Shared input shape for all three single-job actions. The action
 *  kind is encoded in the Tauri command name (`retry_job` /
 *  `remove_job` / `promote_job`); the body itself is identical.
 */
export type JobActionArgs = {
	connectionId: string,
	queueId: QueueId,
	jobId: string,
};

export type JobActionCapabilities = {
	// Retry, remove and promote one job.
	single: boolean,
	// The same on many jobs of a queue, as one action.
	bulk: boolean,
	add: boolean,
};

/**
 *  Reply for all three single-job actions. `new_state` is the
 *  resulting BullMQ state on success (`waiting` for retry/promote,
 *  `None` for remove since the job no longer exists). `action` is
 *  the verb a frontend can use in success toasts ("retry" /
 *  "remove" / "promote") without re-deriving from the command name.
 */
export type JobActionResult = {
	jobId: string,
	newState: JobState | null,
	action: string,
};

export type JobLogsOutput = {
	lines: string[],
	total: number,
	hasMore: boolean,
};

/**
 *  A job: its queue's id, the queue's name for display, and the job's id
 *  within the queue.
 */
export type JobRef = {
	queueId: QueueId,
	queueName: string,
	id: string,
};

export type JobSort = {
	field: JobSortField,
	descending: boolean,
};

export type JobSortField = 
// Job name, then id.
"name" | 
// `timestamp`: when the job was added.
"queuedAt" | 
// `finishedOn − processedOn`; jobs without a duration go last.
"duration";

/**
 *  A job state, by its code: the common lifecycle (`waiting`, `active`,
 *  `completed`, `failed`, `delayed`, `paused`) and whatever states the
 *  connection's backend adds (BullMQ: `prioritized`, `waitingChildren`,
 *  `stalled`). The backend that receives one resolves it against the
 *  states it declares.
 */
export type JobState = string;

