/**
 *  Discriminated auth-method union.
 * 
 *  `KeyFile` carries a path string; we do NOT read or validate the file
 *  contents here (the BullMQ backend's `ssh_tunnel` does at connect time). `Password` is a marker
 *  variant: the actual password text lives in the keychain at
 *  `{connection_id}::ssh`.
 */
export type SshAuthMethod = { kind: "keyFile"; keyFilePath: string } | { kind: "password" };

/**
 *  Captured on the first successful SSH-tunneled
 *  connection so the form's success banner can surface "First connect
 *  to bastion: host key pinned (`<short fingerprint>`)" to the user
 *  (TOFU UX). `was_new_pin == false` is silent (the keychain already
 *  had the pin from an earlier connect).
 */
export type SshHostKeyPin = {
	fingerprint: string,
	wasNewPin: boolean,
};

export type SshJumpHost = {
	host: string,
	port: number,
	user: string,
};

/**
 *  Read-shape exposed to the frontend. The structural SSH tunnel config
 *  (host / port / user / auth method / optional jump host): no password.
 */
export type SshTunnelConfig = {
	host: string,
	port: number,
	user: string,
	auth: SshAuthMethod,
	jumpHost: SshJumpHost | null,
};

/**
 *  How many jobs a queue holds in each state, by state code (`waiting`,
 *  `prioritized`…). A state the backend did not count is absent: read it as
 *  zero.
 */
export type StateCounts = { [key in string]: number };

/**
 *  The look a state borrows from the lifecycle's: pending as waiting,
 *  running as active, success as completed, warning as delayed, danger
 *  as failed.
 */
export type StateTone = "neutral" | "pending" | "running" | "success" | "warning" | "danger";

/**
 *  The Timeline's dragged window: done, failed, wait p95
 *  against the rest of the visible range, failures by cause.
 */
export type SummarizeWindowArgs = {
	connectionId: string,
	// The window, ms since epoch.
	fromMs: number,
	toMs: number,
	// Start of the visible range: "usual" is the range outside the window.
	rangeFromMs: number,
};

export type TestConnectionArgs = {
	// The kind of backend (`bullmq-redis`): the test reaches a Redis.
	backend: string,
	/**
	 *  The endpoint to test, as the backend describes it. Validated (the CA
	 *  PEM, the SSH tunnel) before any connection is opened.
	 */
	endpoint: JsonValue,
	password: string | null,
	/**
	 *  SSH password for the Test call when the endpoint's tunnel uses
	 *  password auth. The form passes the current draft value (which is
	 *  empty in edit mode unless the user typed a new password, same UX as
	 *  the Redis password). `None` falls back to key-file auth or anonymous
	 *  attempt.
	 */
	sshPassword?: string | null,
	/**
	 *  Editing a saved connection: a blank password (Redis or
	 *  SSH) means "the one already in the keychain", as it does on save, so
	 *  the test does not fail for a password the form never shows.
	 */
	savedConnectionId?: string | null,
};

export type TestConnectionError = { kind: "authFailed" } | { kind: "cannotReach"; reason: string } | { kind: "timeout" } | { kind: "tlsHandshake"; reason: string } | 
/**
 *  The SSH tunnel step failed before Redis was reached.
 *  The form's `renderTestError` switch renders `reason` verbatim.
 *  Three distinct backend variants (`SshAuthFailed`,
 *  `SshKeyFileError`, `SshTunnelFailed`) collapse to this single
 *  form-facing arm; the form doesn't branch on the SSH sub-kind.
 */
{ kind: "sshTunnel"; reason: string } | { kind: "other"; reason: string };

export type TestConnectionResult = {
	success: boolean,
	redisVersion: string | null,
	error: TestConnectionError | null,
	/**
	 *  Populated when this Test successfully established
	 *  an SSH tunnel. `None` for non-SSH connections AND for failed
	 *  tests (the tunnel-open error is in `error` instead).
	 */
	sshHostKeyPinned: SshHostKeyPin | null,
	// What the test found on a server that answered.
	probe?: ConnectionProbe | null,
};

/**
 *  Completed / failed counts over time for every queue of a
 *  connection, from BullMQ's native per-minute metrics only: cheap
 *  enough to draw a heat strip per queue. A queue that records no metrics
 *  says so (`metrics_off`) instead of drawing zeros.
 */
export type Throughput = {
	range: MetricsRange,
	bucketMs: number,
	bucketStartsMs: number[],
	queues: QueueThroughput[],
	// Sum over the queues that record metrics.
	completed: number[],
	failed: number[],
	// Queues without native metrics, out of `queues.len()`.
	metricsOffQueues: number,
};

export type Topology = {
	links: FlowLink[],
	queues: QueueFlowStats[],
};

export type UpdateCheckResult = {
	available: boolean,
	// Newly-available version (when `available == true`).
	version: string | null,
	// Release notes of that version, as published in the feed.
	notes?: string | null,
	// The running app's version.
	currentVersion: string,
	/**
	 *  `true` when the check was suppressed by the disable mechanism
	 *  (env var / CLI flag).
	 */
	disabled: boolean,
	// Reason for the disable (for the UI's status display).
	disabledReason: string | null,
};

export type UpdateConnectionArgs = {
	id: string,
	name: string,
	// The kind of backend that serves it (`bullmq-redis`).
	backend: string,
	/**
	 *  The whole endpoint: it replaces the saved one. Checked by the backend
	 *  of its kind before anything is written.
	 */
	endpoint: JsonValue,
	/**
	 *  `None` = leave the keychain entry untouched.
	 *  `Some("")` = rejected as `InvalidInput` (the `Option<String>` is the
	 *  "unchanged" sentinel, an empty string is presumed to be a UI bug).
	 *  `Some(value)` = overwrite the keychain entry under the same connection id.
	 */
	password: string | null,
	/**
	 *  SSH password (Option<String> with the same semantics as
	 *  `password`):
	 *    - `None` → leave keychain entry untouched.
	 *    - `Some("")` → REJECT as `InvalidInput` (presumed UI bug).
	 *    - `Some(value)` → overwrite at `{id}::ssh`.
	 * 
	 *  A key-file tunnel, or an endpoint without the saved tunnel, deletes
	 *  the `{id}::ssh` entry: this field is then ignored.
	 */
	sshPassword: string | null,
	/**
	 *  Where the connection lives. Sending a different group /
	 *  environment than the current one **moves** the connection.
	 */
	group: GroupSelector,
	environment: EnvironmentSelector,
	/**
	 *  "Read-only until I unlock it": `Some` sets the lock the
	 *  connection starts with; `None` leaves it (moving into Production
	 *  still locks).
	 */
	locked?: boolean | null,
};

// Args for `upsert_scheduler`. Saving an existing `scheduler.id` edits it.
export type UpsertSchedulerArgs = {
	connectionId: string,
	queueId: QueueId,
	scheduler: SchedulerSpec,
};

export type UsualDuration = {
	queueName: string,
	name: string,
	medianMs: number,
	// Completed jobs the median is taken over.
	samples: number,
};

export type WindowCause = {
	signature: string,
	sample: string,
	count: number,
	// The jobs of the cause in the window, newest first ("Open N jobs").
	jobs: JobRef[],
};

export type WindowSummary = {
	fromMs: number,
	toMs: number,
	done: number,
	failed: number,
	// What the rest of the visible range did, scaled to the window's length.
	usualDone: number,
	usualFailed: number,
	// Time from added to started, 95th percentile; `None` = no job started.
	waitP95Ms: number | null,
	usualWaitP95Ms: number | null,
	// Most frequent first.
	causes: WindowCause[],
	// Jobs looked at, and whether older ones were left out.
	scanned: number,
	scanCapped: boolean,
};

export type WorkerCapabilities = {
	list: boolean,
	count: boolean,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

